starterCodeJson.code:
// Question 1 — the cover page of the SRS template (Wiegers): fill every field, remove every <placeholder>.
const COVER = {
  title: 'Software Requirements Specification',
  project: '<Project name>',
  version: '<1.0>',
  preparedBy: '<Your full name - Student ID>',
  organization: '<Organization>',
  dateCreated: '<yyyy-mm-dd>',
};

// Question 2 — context diagram as a Mermaid flowchart (paste into https://mermaid.live to see it).
// The system = ONE circle. External entities = rectangles. One labelled arrow per direction; label = the DATA.
const CONTEXT_DIAGRAM = `
flowchart LR
  S((System name))
  E1[External entity] -->|data in| S
  S -->|data out| E1
`;

// Question 3 — use case diagram (PlantUML: paste into https://www.plantuml.com/plantuml) + the two tables of the template.
const USE_CASE_DIAGRAM = `
@startuml
left to right direction
actor "Actor name" as A1
rectangle "System name" {
  usecase "Verb Object" as UC1
}
A1 --> UC1
@enduml
`;

// Table "# | Actor | Description" — one object per actor of the diagram (same names).
const ACTORS = [
  { name: 'Actor name', description: '' },
];

// Table "# | Use Case | Actors | Description" — one object per use case (same names as the diagram).
const USE_CASES = [
  { id: 'UC-01', name: 'Verb Object', actors: ['Actor name'], description: '' },
];

// Question 4 — state transition diagram (Mermaid stateDiagram-v2) + the state table of the template.
const STATE_DIAGRAM = `
stateDiagram-v2
  [*] --> FirstState
  FirstState --> SecondState : event [guard] / action
  SecondState --> [*]
`;

// Table "# | State | Description" — one object per state of the diagram.
const STATES = [
  { name: 'FirstState', description: '' },
];

solutionCodeJson.code:
// Question 1 — copy the system name EXACTLY from the paper; the grader cannot know your name, any real one passes.
const COVER = {
  title: 'Software Requirements Specification',
  project: 'LostLink AI-Assisted Lost & Found Platform',
  version: '1.0',
  preparedBy: 'Nguyen Van An - SE180123',
  organization: 'FPT University, Ho Chi Minh City campus',
  dateCreated: '2026-11-05',
};

// Question 3 — use case diagram consistent with Question 2 (same actors), plus the actor and use case tables.
const USE_CASE_DIAGRAM = `@startuml
left to right direction
actor Finder
actor Owner
actor "Security Officer" as SO
actor "Lost & Found Manager" as MG
actor "Campus SSO" as SSO
actor "Notification Service" as NS
actor "Charity Partner" as CP
actor "Campus Police" as PO
rectangle "LostLink AI-Assisted Lost & Found Platform" {
  usecase "Sign In" as UC1
  usecase "Log Found Item" as UC2
  usecase "File Lost Report" as UC3
  usecase "Attach Item Photos" as UC4
  usecase "Respond to Match Suggestion" as UC5
  usecase "Book Pick-up Slot" as UC6
  usecase "Confirm Item Receipt" as UC7
  usecase "Review Uncertain Match" as UC8
  usecase "Record Handover" as UC9
  usecase "Verify Owner Identity" as UC10
  usecase "Release Unclaimed Items" as UC11
  usecase "Transfer High-Value Items" as UC12
  usecase "Dispose Perishable Items" as UC13
  usecase "Configure Matching Rules" as UC14
  usecase "View Monthly Statistics" as UC15
  usecase "Send Notification" as UC16
}
Finder --> UC1
Owner --> UC1
SO --> UC1
MG --> UC1
UC1 --> SSO
Finder --> UC2
Owner --> UC3
UC4 ..> UC3 : <<extend>>
Owner --> UC5
Owner --> UC6
SO --> UC7
SO --> UC8
SO --> UC9
UC9 ..> UC10 : <<include>>
SO --> UC11
UC11 --> CP
SO --> UC12
UC12 --> PO
SO --> UC13
MG --> UC14
MG --> UC15
UC5 ..> UC16 : <<include>>
UC16 --> NS
@enduml
`;

const ACTORS = [
  {
    name: 'Finder',
    description: 'A student or staff member who finds an item on campus, logs it with photos and hands it to the security desk.',
  },
  {
    name: 'Owner',
    description: 'A student or staff member who lost an item, files a lost report, answers match suggestions and picks the item up.',
  },
  {
    name: 'Security Officer',
    description: 'Staff at the security desk who receive items, review uncertain matches, verify owners and record handovers.',
  },
  {
    name: 'Lost & Found Manager',
    description: 'Configures matching thresholds, item categories and retention periods and reads the monthly statistics.',
  },
  {
    name: 'Campus SSO',
    description: 'External university sign-on service that authenticates every user and returns an identity token.',
  },
  {
    name: 'Notification Service',
    description: 'External university service that delivers the e-mails and in-app notifications sent by LostLink.',
  },
  {
    name: 'Charity Partner',
    description: 'External charity organisation that receives the monthly list of unclaimed items and collects them.',
  },
  {
    name: 'Campus Police',
    description: 'External police unit that receives the transfer record of high-value items left unclaimed for 60 days.',
  },
];

const USE_CASES = [
  {
    id: 'UC-01',
    name: 'Sign In',
    actors: ['Finder', 'Owner', 'Security Officer', 'Lost & Found Manager', 'Campus SSO'],
    description: 'Any user signs in with the university account; Campus SSO authenticates the user and returns an identity token.',
  },
  {
    id: 'UC-02',
    name: 'Log Found Item',
    actors: ['Finder'],
    description: 'The finder records a found item with photos, the place and the time it was found.',
  },
  {
    id: 'UC-03',
    name: 'File Lost Report',
    actors: ['Owner'],
    description: 'The owner describes the lost item and the approximate place so the AI engine can search for it.',
  },
  {
    id: 'UC-04',
    name: 'Attach Item Photos',
    actors: [],
    description: 'Optional extension of filing a lost report: the owner adds photos of the lost item when available.',
  },
  {
    id: 'UC-05',
    name: 'Respond to Match Suggestion',
    actors: ['Owner'],
    description: 'The owner views a suggested match with its photo and confirms or rejects that the item is theirs.',
  },
  {
    id: 'UC-06',
    name: 'Book Pick-up Slot',
    actors: ['Owner'],
    description: 'After confirming a match the owner books a time to collect the item at the security desk.',
  },
  {
    id: 'UC-07',
    name: 'Confirm Item Receipt',
    actors: ['Security Officer'],
    description: 'The officer confirms that a logged item has arrived at the desk and assigns it a locker number.',
  },
  {
    id: 'UC-08',
    name: 'Review Uncertain Match',
    actors: ['Security Officer'],
    description: 'The officer checks a pair with a similarity score between 0.50 and 0.80 and approves or rejects it.',
  },
  {
    id: 'UC-09',
    name: 'Record Handover',
    actors: ['Security Officer'],
    description: 'The officer records that the item was returned to its owner after verifying the owner identity.',
  },
  {
    id: 'UC-10',
    name: 'Verify Owner Identity',
    actors: [],
    description: 'Included in every handover: the officer checks the student card or the answer to the secret question.',
  },
  {
    id: 'UC-11',
    name: 'Release Unclaimed Items',
    actors: ['Security Officer', 'Charity Partner'],
    description: 'Items unclaimed for 60 days that are not high value are listed monthly for the charity partner to collect.',
  },
  {
    id: 'UC-12',
    name: 'Transfer High-Value Items',
    actors: ['Security Officer', 'Campus Police'],
    description: 'High-value items unclaimed for 60 days are handed to the campus police with a transfer record.',
  },
  {
    id: 'UC-13',
    name: 'Dispose Perishable Items',
    actors: ['Security Officer'],
    description: 'Food and drinks are disposed of 24 hours after they were received and the disposal is recorded.',
  },
  {
    id: 'UC-14',
    name: 'Configure Matching Rules',
    actors: ['Lost & Found Manager'],
    description: 'The manager sets the similarity thresholds, item categories and retention periods used by the platform.',
  },
  {
    id: 'UC-15',
    name: 'View Monthly Statistics',
    actors: ['Lost & Found Manager'],
    description: 'The manager reads items found, return rate and average days to return for each month.',
  },
  {
    id: 'UC-16',
    name: 'Send Notification',
    actors: ['Notification Service'],
    description: 'Included whenever a user must be told something: the message is delivered by the notification service.',
  },
];

// Question 4 — state machine of the object: conditions as states, event [guard] / action on every transition.
const STATE_DIAGRAM = `stateDiagram-v2
  [*] --> Logged : item logged by finder
  state "In Custody" as InCustody
  state "Under Review" as UnderReview
  state "Match Suggested" as MatchSuggested
  state "Claim Pending" as ClaimPending
  state "Transferred to Police" as Transferred
  Logged --> InCustody : receipt confirmed by officer / assign locker
  Logged --> Disposed : 24 hours elapsed [perishable item]
  InCustody --> MatchSuggested : AI match found [similarity >= 0.80] / notify owner
  InCustody --> UnderReview : AI match found [0.50 <= similarity < 0.80]
  UnderReview --> MatchSuggested : officer approves match / notify owner
  UnderReview --> InCustody : officer rejects match
  MatchSuggested --> ClaimPending : owner confirms match
  MatchSuggested --> InCustody : owner rejects match
  ClaimPending --> Returned : handover recorded [identity verified]
  ClaimPending --> InCustody : claim expires [7 days without pick-up]
  InCustody --> Donated : monthly release [unclaimed 60 days and not high value] / add to donation list
  InCustody --> Transferred : retention ends [unclaimed 60 days and high value] / create transfer record
  InCustody --> Disposed : 24 hours elapsed [perishable item]
  Returned --> [*]
  Donated --> [*]
  Transferred --> [*]
  Disposed --> [*]
`;

const STATES = [
  {
    name: 'Logged',
    description: 'The finder has recorded the item in LostLink but the security desk has not received it yet.',
  },
  {
    name: 'In Custody',
    description: 'The item is stored in a numbered locker at the security desk and is available for AI matching.',
  },
  {
    name: 'Under Review',
    description: 'The AI found a possible owner with a medium similarity score and a security officer must decide.',
  },
  {
    name: 'Match Suggested',
    description: 'A likely owner has been notified with the matched photo and must confirm or reject the match.',
  },
  {
    name: 'Claim Pending',
    description: 'The owner confirmed the match and has seven days to pick the item up at the desk.',
  },
  {
    name: 'Returned',
    description: 'The owner identity was verified and the handover was recorded; the case is closed successfully.',
  },
  {
    name: 'Donated',
    description: 'An ordinary item stayed unclaimed for sixty days and was released to the charity partner.',
  },
  {
    name: 'Transferred to Police',
    description: 'A high-value item stayed unclaimed for sixty days and was handed to the campus police.',
  },
  {
    name: 'Disposed',
    description: 'A perishable item was thrown away twenty-four hours after it was received, as the policy requires.',
  },
];

